#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>

#include <cstdlib>
#include <iostream>
#include <string>

int main() {
  const char* configuredPort = std::getenv("PORT");
  const int port = configuredPort == nullptr ? 8080 : std::atoi(configuredPort);
  const int server = ::socket(AF_INET, SOCK_STREAM, 0);
  if (server < 0) { std::perror("socket"); return 1; }
  int reuse = 1;
  ::setsockopt(server, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse));

  sockaddr_in address{};
  address.sin_family = AF_INET;
  address.sin_addr.s_addr = htonl(INADDR_ANY);
  address.sin_port = htons(static_cast<unsigned short>(port));
  if (::bind(server, reinterpret_cast<sockaddr*>(&address), sizeof(address)) < 0) {
    std::perror("bind"); ::close(server); return 1;
  }
  if (::listen(server, 32) < 0) { std::perror("listen"); ::close(server); return 1; }
  std::cout << "Listening on 0.0.0.0:" << port << std::endl;

  const std::string body = "<!doctype html><html><meta charset='utf-8'><title>C++ workspace</title><body><h1>Hello from Jahaziel</h1><p>Edit main.cpp and reload this preview.</p></body></html>\n";
  while (true) {
    const int client = ::accept(server, nullptr, nullptr);
    if (client < 0) continue;
    char request[1024];
    (void)::recv(client, request, sizeof(request), 0);
    const std::string response = "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: "
        + std::to_string(body.size()) + "\r\nConnection: close\r\n\r\n" + body;
    (void)::send(client, response.data(), response.size(), MSG_NOSIGNAL);
    ::close(client);
  }
}
